CREATE TABLE "AdminEmail" ("id" TEXT NOT NULL PRIMARY KEY,"email" TEXT NOT NULL,"isDefault" BOOLEAN NOT NULL DEFAULT false,"addedBy" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "AdminEmail_email_key" ON "AdminEmail"("email");
CREATE TABLE "Session" ("id" TEXT NOT NULL PRIMARY KEY,"tokenHash" TEXT NOT NULL,"email" TEXT NOT NULL,"googleSub" TEXT NOT NULL,"name" TEXT,"picture" TEXT,"expiresAt" DATETIME NOT NULL,"lastSeenAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt"); CREATE INDEX "Session_email_idx" ON "Session"("email");
CREATE TABLE "Profile" ("id" TEXT NOT NULL PRIMARY KEY DEFAULT 'main',"name" TEXT NOT NULL,"headline" TEXT NOT NULL,"rotatingTitles" TEXT NOT NULL DEFAULT '[]',"description" TEXT NOT NULL,"location" TEXT,"education" TEXT,"currentRole" TEXT,"hobbies" TEXT,"photoKey" TEXT,"ogImageKey" TEXT,"available" BOOLEAN NOT NULL DEFAULT true,"availabilityNote" TEXT,"updatedAt" DATETIME NOT NULL);
CREATE TABLE "Project" ("id" TEXT NOT NULL PRIMARY KEY,"slug" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"year" INTEGER NOT NULL,"techStack" TEXT NOT NULL DEFAULT '[]',"githubUrl" TEXT,"demoUrl" TEXT,"thumbnailKey" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,"featured" BOOLEAN NOT NULL DEFAULT false,"published" BOOLEAN NOT NULL DEFAULT false,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL); CREATE UNIQUE INDEX "Project_slug_key" ON "Project"("slug"); CREATE INDEX "Project_published_sortOrder_idx" ON "Project"("published","sortOrder");
CREATE TABLE "SkillCategory" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "Skill" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,"categoryId" TEXT NOT NULL,CONSTRAINT "Skill_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "SkillCategory"("id") ON DELETE CASCADE ON UPDATE CASCADE); CREATE INDEX "Skill_categoryId_idx" ON "Skill"("categoryId");
CREATE TABLE "Experience" ("id" TEXT NOT NULL PRIMARY KEY,"title" TEXT NOT NULL,"organization" TEXT NOT NULL,"startDate" TEXT NOT NULL,"endDate" TEXT,"description" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "Certification" ("id" TEXT NOT NULL PRIMARY KEY,"kind" TEXT NOT NULL,"title" TEXT NOT NULL,"issuer" TEXT NOT NULL,"year" INTEGER NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "SocialLink" ("id" TEXT NOT NULL PRIMARY KEY,"platform" TEXT NOT NULL,"url" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "Message" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"body" TEXT NOT NULL,"ipHash" TEXT,"isRead" BOOLEAN NOT NULL DEFAULT false,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "Message_isRead_createdAt_idx" ON "Message"("isRead","createdAt");
CREATE TABLE "RateLimit" ("key" TEXT NOT NULL PRIMARY KEY,"count" INTEGER NOT NULL,"resetAt" DATETIME NOT NULL);
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL PRIMARY KEY,"actorEmail" TEXT,"action" TEXT NOT NULL,"target" TEXT,"ip" TEXT,"userAgent" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");
